@dataclass(kw_only=True)
class RunnerHello:
    """RunnerHello is sent by the runner immediately after the WS upgrade. Authentication is the Authorization: Bearer header on the upgrade request — the server resolves the token to a Machine row by hash. The Hello payload is environmental detail the server records for display + binary-serving (hostname, OS, etc.); it carries no identity claims of its own. The machine label is server-side state, returned to the runner via Welcome.MachineName."""
    hostname: str  # os.Hostname()
    os: str  # GOOS
    arch: str  # GOARCH
    user: str  # os/user.Current().Username
