# SeedSource discriminates which store provided a seeded file. Lets the runner reconcile each provider against its own endpoint set without the bridge needing per-source message types.
SeedSource = str

SeedSourceAgentStore: SeedSource = "agent-store"
SeedSourceSkillStore: SeedSource = "skill-store"

# SeedOp is the kind of change the runner should apply to a seeded path.
SeedOp = str

SeedOpUpsert: SeedOp = "upsert"
SeedOpDelete: SeedOp = "delete"


@dataclass(kw_only=True)
class RunnerSeedDelta:
    """RunnerSeedDelta is a single-file change pushed to a runner immediately after the bridge records a new authoritative version. The runner must:   1. Compute the sha256 of the local file at InstallPath, if any.  2. If the local sha differs from ExpectedPriorSHA (drift), POST the local     bytes to the source's /seed/drift endpoint *first*. Only if that call     succeeds may it proceed to step 3.  3. GET the new content from the source's version endpoint and write it     atomically (tmp + rename).  ExpectedPriorSHA empty = the runner has never seen this file (first push). In that case any pre-existing content at InstallPath is treated as drift."""
    source: SeedSource
    op: SeedOp
    tracked_id: int  # ID in the source store
    version_id: int | None = None  # version to fetch on upsert
    install_path: str  # $HOME-relative
    new_sha: str | None = None  # sha of the new content (upsert only)
    expected_prior_sha: str | None = None  # last-pushed sha bridge thinks runner has


@dataclass(kw_only=True)
class RunnerSeedSnapshot:
    """RunnerSeedSnapshot tells the runner to do a full manifest reconcile against the named source. Sent on connect and after a bridge-side scan completes. The actual manifest is fetched via HTTP — this message is just the trigger + opportunity to bundle metadata (e.g. ticket count) for telemetry."""
    source: SeedSource
    entry_count: int | None = None  # bridge's count, for sanity logging
    reason: str | None = None  # "connect", "scan", "manual", …


