# SessionMode selects the I/O contract for a session at spawn time.  SessionModeEvents (default) runs the harness in its current structured- events posture: stdin/stdout NDJSON between server and harness, normalized msg.Event stream over GET /sessions/{id}/events.  SessionModePTY runs the harness's upstream CLI inside a pseudoterminal the caller attaches to over a WebSocket at GET /sessions/{id}/attach. Bytes pass through verbatim — no msg.Event derivation. Per-harness opt-in via bridge.PTYCapableHarness.
SessionMode = str

SessionModeEvents: SessionMode = "events"
SessionModePTY: SessionMode = "pty"

# SessionType categorizes a session by how it is being used. Bridge-side behavior that depends on category (e.g. completion notifications, SSE keepalive policy) reads SessionType. Behavior that depends on which specific service originated the session reads Source.  Will be required on Create — the field is currently optional in the wire format for backward compatibility while callers are updated. Enforcement flips on once all callers populate it. See MIGRATION-session-identity.md.
SessionType = str

SessionTypeInteractive: SessionType = "interactive"
SessionTypeAutonomous: SessionType = "autonomous"
SessionTypeSystem: SessionType = "system"


@dataclass(kw_only=True)
class ManagedSession:
    """ManagedSession is a session as tracked by llm-bridge-server. This is the server's lightweight session management entity, distinct from [Session] which models rich agent-level state (usage, tasks, context).  Identifier fields:   - SessionID: canonical session id. Caller-minted on Create or     server-minted (br_<nanos>) when omitted. Stable from creation.   - HarnessSessionID: the canonical harness session ID (e.g. CC UUID).     Rotates on resume/fork. Empty until the harness reports it on first     event. Will move to adapter-private storage in Phase II.C."""
    session_id: str
    harness_session_id: str | None = None
    display_name: str
    harness: Harness
    instance_id: str | None = None
    state: str
    pid: int | None = None
    agent_id: str | None = None
    spawner_id: str | None = None
    parent_id: str | None = None
    harness_config: dict[str, Any] | None = None  # opaque harness-specific config
    info: SessionInfo | None = None  # latest session info reported by the harness
    folder_name: str | None = None  # user-assigned sidebar folder; empty = unfiled
    source: str | None = None  # origin tag carried from the creator (e.g. "scheduler", "autoworker"); empty = interactive
    session_type: SessionType | None = None  # category of session; required on Create once enforcement flips on
    mode: SessionMode | None = None  # I/O mode picked at creation; empty = events (legacy default)
    created_at: str
    updated_at: str


