@dataclass(kw_only=True)
class Session:
    """Session represents an agent session across any harness."""
    id: str
    harness: Harness
    state: SessionState
    agent: str | None = None
    orchestrator: str | None = None
    model: str | None = None
    created_at: str
    last_active: str
    ended_at: str | None = None
    context_tokens: int | None = None
    context_limit: int | None = None
    total_usage: TokenUsage
    total_cost: Cost | None = None
    turn_count: int
    config: dict[str, Any] | None = None
    tasks: list[SessionTask] | None = None
    active_request: str | None = None
    _overflow: dict[str, dict[str, Any]] | None = None


@dataclass(kw_only=True)
class SessionTask:
    """SessionTask tracks a task within a session."""
    content: str
    status: str
    active_form: str | None = None


@dataclass(kw_only=True)
class StoredSession:
    """StoredSession represents a session discovered on disk from a harness's native storage (e.g. ~/.claude/projects/ or ~/.codex/sessions/). These are sessions that exist outside the llm-bridge-server's own store."""
    harness_session_id: str
    bridge_session_id: str | None = None
    harness: Harness
    project: str | None = None  # project directory or context
    prompt: str | None = None  # initial prompt snippet
    created_at: str
    updated_at: str  # file modification time
    path: str  # on-disk path to session file
    turn_count: int | None = None  # approximate number of turns
    source: str | None = None


