@dataclass(kw_only=True)
class FolderList:
    """FolderList is the ordered list of user-defined folder names for organizing sessions in the sidebar. Folder assignment per session lives on [ManagedSession.FolderName] so it travels with the session row."""
    folder_order: list[str]


@dataclass(kw_only=True)
class CreateFolderRequest:
    """CreateFolderRequest is the body for POST /folders."""
    name: str


@dataclass(kw_only=True)
class RenameFolderRequest:
    """RenameFolderRequest is the body for PUT /folders/{name}."""
    new_name: str


@dataclass(kw_only=True)
class SetSessionFolderRequest:
    """SetSessionFolderRequest is the body for PUT /sessions/{id}/folder. An empty Folder string clears the assignment (un-files the session)."""
    folder: str


@dataclass(kw_only=True)
class FileInactiveRequest:
    """FileInactiveRequest is the body for POST /admin/file-inactive.  Sessions whose updated_at is older than InactiveDays and which are not already filed move into Folder. Folder is auto-created if it doesn't exist in the registry."""
    inactive_days: int
    folder: str


@dataclass(kw_only=True)
class FileInactiveResponse:
    """FileInactiveResponse reports the outcome of a file-inactive sweep."""
    moved: int
    folder: str
    ids: list[str] | None = None


@dataclass(kw_only=True)
class ArchiveOldRequest:
    """ArchiveOldRequest is the body for POST /admin/archive-old.  Every session (in any folder other than the Archive folder) whose updated_at is older than InactiveDays and which is not currently running moves into the Archive folder. The Archive folder is auto-created if it doesn't exist in the registry."""
    inactive_days: int


@dataclass(kw_only=True)
class ArchiveOldResponse:
    """ArchiveOldResponse reports the outcome of an archive-old sweep."""
    moved: int
    ids: list[str] | None = None


@dataclass(kw_only=True)
class MarkSessionDoneRequest:
    """MarkSessionDoneRequest is the body for POST /sessions/{id}/mark-done.  Done=true atomically (a) emits an EventSessionState{State: completed} through the central derivation pipeline so the row state and SSE feed agree, and (b) moves the session into the canonical Archive folder. Done=false reverses both: state goes to idle, folder is cleared.  If new events flow in after the manual mark, derivation overwrites the state (e.g. a new tool_call flips back to tool_running). That's intentional — the session re-engaging visibly says "no longer done"."""
    done: bool


