# StreamEventType identifies the kind of streaming event.
StreamEventType = str

StreamEventStart: StreamEventType = "stream_start"
StreamEventContentBlockStart: StreamEventType = "content_block_start"
StreamEventContentBlockDelta: StreamEventType = "content_block_delta"
StreamEventContentBlockStop: StreamEventType = "content_block_stop"
StreamEventMessageDelta: StreamEventType = "message_delta"
StreamEventMessageStop: StreamEventType = "message_stop"
StreamEventPing: StreamEventType = "ping"
StreamEventError: StreamEventType = "error"


@dataclass(kw_only=True)
class StreamEvent:
    """StreamEvent is the unified streaming event type. Follows Anthropic's granular model (most expressive) and synthesizes block-level events for providers that don't have them (OpenAI, Gemini)."""
    type: StreamEventType
    start: StreamStart | None = None
    block_start: BlockStart | None = None
    block_delta: BlockDelta | None = None
    block_stop: BlockStop | None = None
    msg_delta: MessageDelta | None = None
    error: StreamError | None = None
    raw: dict[str, Any] | None = None
    extensions: dict[str, dict[str, Any]] | None = None
    _overflow: dict[str, dict[str, Any]] | None = None


@dataclass(kw_only=True)
class StreamStart:
    """StreamStart carries initial message metadata."""
    id: str
    model: str
    provider: Provider
    usage: TokenUsage


@dataclass(kw_only=True)
class BlockStart:
    """BlockStart signals a new content block beginning."""
    index: int
    block: ContentBlock

# DeltaType identifies the kind of streaming delta.
DeltaType = str

DeltaText: DeltaType = "text_delta"
DeltaInputJSON: DeltaType = "input_json_delta"
DeltaThinking: DeltaType = "thinking_delta"
DeltaSignature: DeltaType = "signature_delta"
DeltaAudio: DeltaType = "audio_delta"


@dataclass(kw_only=True)
class BlockDelta:
    """BlockDelta carries incremental content for a block."""
    index: int
    type: DeltaType
    text: str | None = None
    partial_json: str | None = None
    thinking: str | None = None
    signature: str | None = None
    audio_data: str | None = None


@dataclass(kw_only=True)
class BlockStop:
    """BlockStop signals a content block has finished."""
    index: int


@dataclass(kw_only=True)
class MessageDelta:
    """MessageDelta carries end-of-message metadata."""
    stop_reason: StopReason
    native_stop_reason: str | None = None
    stop_sequence: str | None = None
    usage: TokenUsage


@dataclass(kw_only=True)
class StreamError:
    """StreamError represents an error during streaming."""
    type: str
    message: str
    code: str | None = None
    retryable: bool | None = None
    retry_after_ms: int | None = None
    status_code: int | None = None


